const express = require('express');
const { createYoga, createSchema } = require('graphql-yoga');
const { GraphQLError } = require('graphql');
const { MongoClient, ObjectId } = require('mongodb');

const client = new MongoClient(process.env.MONGO_URI);
const db = client.db('helpdesk');

const typeDefs = `
  type SupportTicket @key(fields: "id") {
    id: ID!
    subject: String!
    status: String!
    priority: String!
    customerEmail: String!
    internalAgentNotes: String
  }

  type Query {
    version: String
  }
`;

const resolvers = {
  SupportTicket: {
    __resolveReference: async (representation, { db, user }) => {
      if (!user) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }

      let query = { _id: new ObjectId(representation.id) };

      // Restrict customer access to tickets belonging to their company
      if (user.role !== 'SUPPORT_AGENT') {
        query.companyId = user.companyId;
      }

      const ticket = await db.collection('tickets').findOne(query);

      if (!ticket) {
        throw new GraphQLError('Ticket not found or permission denied', {
          extensions: { code: 'FORBIDDEN' }
        });
      }

      // Sanitize internal agent notes if the caller is not an internal agent
      if (user.role !== 'SUPPORT_AGENT') {
        delete ticket.internalAgentNotes;
      }

      return ticket;
    }
  }
};

const app = express();
const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  context: ({ req }) => ({
    db,
    user: req.session ? req.session.user : null
  })
});

app.use('/graphql', yoga);
app.listen(3030);
